func (ctrl *MainController) bindDonationButtons(builder *gtk.Builder) {
	if icon, ok := castObject[*gtk.Image](builder, "settings_liberapay_icon"); ok && icon != nil {
		if tex, err := gdk.NewTextureFromBytes(glib.NewBytesWithGo([]byte(liberapaySVG))); err == nil && tex != nil {
			icon.SetFromPaintable(tex)
		}
	}
	if icon, ok := castObject[*gtk.Image](builder, "settings_bmac_icon"); ok && icon != nil {
		if tex, err := gdk.NewTextureFromBytes(glib.NewBytesWithGo([]byte(buyMeACoffeeSVG))); err == nil && tex != nil {
			icon.SetFromPaintable(tex)
		}
	}
	if btn, ok := castObject[*gtk.Button](builder, "settings_donate_liberapay_btn"); ok && btn != nil {
		btn.ConnectClicked(func() {
			_ = media.OpenURL(liberapayURL)
		})
	}
	if btn, ok := castObject[*gtk.Button](builder, "settings_donate_bmac_btn"); ok && btn != nil {
		btn.ConnectClicked(func() {
			_ = media.OpenURL(buyMeACoffeeURL)
		})
	}
}
